import { open, rename, unlink } from "node:fs/promises";
import { crc32 } from "node:zlib";
import { BGCODE_MAGIC } from "./bgcode.ts";

/**
 * Thumbnails written into G-code the way PrusaSlicer writes them, so that printers read them as
 * their own (checked byte for byte against PrusaSlicer 2.9.7's output in the unit tests):
 *
 * - ASCII: right after "; generated by ..." and the empty line under it, one block per image:
 *   "\n;\n; thumbnail[_QOI|_JPG] begin WxH <base64 length>\n", the base64 in lines of 78
 *   characters after "; ", then "; thumbnail[_QOI|_JPG] end\n;\n" (source GCodeThumbnails.hpp).
 * - Binary (libbgcode v1): one thumbnail block (type 5) per image, after the printer metadata
 *   block, uncompressed: type, compression 0, size, then format (0 PNG, 1 JPG, 2 QOI), width,
 *   height, the image, and a CRC32 over all of it when the file header asks for checksums.
 */

export interface ThumbnailSpec {
  width: number;
  height: number;
  /** As the printer profile names it: PNG, JPG, QOI (or something this server does not write). */
  format: string;
}

export interface EncodedThumbnail {
  format: "png" | "qoi";
  width: number;
  height: number;
  data: Buffer;
}

/**
 * The printer profile's thumbnails: "16x16/QOI, 313x173/QOI, 380x285/PNG", or the older form
 * "16x16,220x124" with the format in thumbnails_format (PNG by default).
 */
export function parseThumbnailSpec(thumbnails: string | undefined, legacyFormat?: string): ThumbnailSpec[] {
  const specs: ThumbnailSpec[] = [];
  for (const part of (thumbnails ?? "").split(",")) {
    const match = /^\s*(\d+)\s*x\s*(\d+)\s*(?:\/\s*([A-Za-z0-9_]+))?\s*$/.exec(part);
    if (!match) continue;
    const width = Number(match[1]);
    const height = Number(match[2]);
    if (width < 1 || height < 1) continue;
    specs.push({ width, height, format: (match[3] ?? (legacyFormat?.trim() || "PNG")).toUpperCase() });
  }
  return specs;
}

const ASCII_TAG: Record<EncodedThumbnail["format"], string> = { png: "thumbnail", qoi: "thumbnail_QOI" };
const BGCODE_FORMAT: Record<EncodedThumbnail["format"], number> = { png: 0, qoi: 2 };

export function asciiThumbnailBlock(thumbnail: EncodedThumbnail, eol = "\n"): string {
  const tag = ASCII_TAG[thumbnail.format];
  const encoded = thumbnail.data.toString("base64");
  const lines = [`${eol};${eol}; ${tag} begin ${thumbnail.width}x${thumbnail.height} ${encoded.length}${eol}`];
  for (let at = 0; at < encoded.length; at += 78) lines.push(`; ${encoded.slice(at, at + 78)}${eol}`);
  lines.push(`; ${tag} end${eol};${eol}`);
  return lines.join("");
}

export function bgcodeThumbnailBlock(thumbnail: EncodedThumbnail, withChecksum: boolean): Buffer {
  const head = Buffer.alloc(14);
  head.writeUInt16LE(5, 0); // thumbnail block
  head.writeUInt16LE(0, 2); // not compressed
  head.writeUInt32LE(thumbnail.data.length, 4);
  head.writeUInt16LE(BGCODE_FORMAT[thumbnail.format], 8);
  head.writeUInt16LE(thumbnail.width, 10);
  head.writeUInt16LE(thumbnail.height, 12);
  const block = Buffer.concat([head, thumbnail.data]);
  if (!withChecksum) return block;
  const checksum = Buffer.alloc(4);
  checksum.writeUInt32LE(crc32(block) >>> 0, 0);
  return Buffer.concat([block, checksum]);
}

interface BlockInfo {
  type: number;
  start: number;
  /** Header, parameters and data, without the checksum. */
  length: number;
  end: number;
}

/** The blocks of a binary G-code file, from their headers. */
async function bgcodeBlocks(path: string): Promise<{ checksums: boolean; blocks: BlockInfo[] }> {
  const handle = await open(path, "r");
  try {
    const { size } = await handle.stat();
    const header = Buffer.alloc(10);
    await handle.read(header, 0, 10, 0);
    if (header.toString("ascii", 0, 4) !== BGCODE_MAGIC) throw new Error("Not a binary G-code file.");
    const checksums = header.readUInt16LE(8) === 1;
    const blocks: BlockInfo[] = [];
    const head = Buffer.alloc(12);
    let offset = 10;
    while (offset < size) {
      const { bytesRead } = await handle.read(head, 0, 12, offset);
      if (bytesRead < 8) throw new Error(`The block at byte ${offset} is cut off.`);
      const type = head.readUInt16LE(0);
      const compression = head.readUInt16LE(2);
      const headerSize = compression === 0 ? 8 : 12;
      const dataSize = compression === 0 ? head.readUInt32LE(4) : head.readUInt32LE(8);
      const length = headerSize + (type === 5 ? 6 : 2) + dataSize;
      const end = offset + length + (checksums ? 4 : 0);
      if (end > size) throw new Error(`The block at byte ${offset} runs past the end of the file.`);
      blocks.push({ type, start: offset, length, end });
      offset = end;
    }
    return { checksums, blocks };
  } finally {
    await handle.close();
  }
}

/** Checks every block's CRC32 in a binary G-code file; the first wrong one, or null. */
export async function checkBgcode(path: string): Promise<string | null> {
  let layout: Awaited<ReturnType<typeof bgcodeBlocks>>;
  try {
    layout = await bgcodeBlocks(path);
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
  if (!layout.checksums) return null;
  const handle = await open(path, "r");
  try {
    for (const block of layout.blocks) {
      const data = Buffer.alloc(block.length + 4);
      await handle.read(data, 0, data.length, block.start);
      if ((crc32(data.subarray(0, block.length)) >>> 0) !== data.readUInt32LE(block.length)) return `The checksum of the block at byte ${block.start} is wrong.`;
    }
    return null;
  } finally {
    await handle.close();
  }
}

/**
 * Writes the thumbnails into a G-code file without them, ASCII or binary. The result is written
 * next to it and checked (binary: every checksum and the number of thumbnail blocks; ASCII: the
 * start of the file read back) before it replaces the file. Throws, leaving the file as it was,
 * when the file is not laid out as PrusaSlicer writes it or the check fails.
 */
export async function insertThumbnails(path: string, thumbnails: EncodedThumbnail[], binary: boolean): Promise<void> {
  if (thumbnails.length === 0) return;
  let offset: number;
  let insert: Buffer;
  let check: (temp: string) => Promise<string | null>;
  if (binary) {
    const { checksums, blocks } = await bgcodeBlocks(path);
    if (blocks.some((block) => block.type === 5)) throw new Error("The G-code already holds thumbnails.");
    const printer = blocks.findIndex((block) => block.type === 3);
    if (printer === -1) throw new Error("The G-code has no printer metadata block to put the thumbnails after.");
    offset = blocks[printer]!.end;
    insert = Buffer.concat(thumbnails.map((thumbnail) => bgcodeThumbnailBlock(thumbnail, checksums)));
    check = async (temp) => {
      const wrong = await checkBgcode(temp);
      if (wrong) return wrong;
      const written = (await bgcodeBlocks(temp)).blocks;
      return written.filter((block) => block.type === 5).length === thumbnails.length && written.length === blocks.length + thumbnails.length
        ? null
        : "The written file does not hold the expected blocks.";
    };
  } else {
    const handle = await open(path, "r");
    let head = Buffer.alloc(4096);
    try {
      const { bytesRead } = await handle.read(head, 0, head.length, 0);
      head = head.subarray(0, bytesRead);
    } finally {
      await handle.close();
    }
    const text = head.toString("latin1");
    const first = text.indexOf("\n");
    const second = first === -1 ? -1 : text.indexOf("\n", first + 1);
    if (!text.startsWith("; generated by ") || second === -1 || text.slice(first + 1, second).trim() !== "") {
      throw new Error("The G-code does not start with PrusaSlicer's \"; generated by\" line and an empty line.");
    }
    if (/^; thumbnail(_[A-Z]+)? begin /m.test(text)) throw new Error("The G-code already holds thumbnails.");
    const eol = text[first - 1] === "\r" ? "\r\n" : "\n";
    offset = second + 1;
    insert = Buffer.from(thumbnails.map((thumbnail) => asciiThumbnailBlock(thumbnail, eol)).join(""), "latin1");
    const expected = Buffer.concat([head.subarray(0, offset), insert, head.subarray(offset)]);
    check = async (temp) => {
      const handle = await open(temp, "r");
      try {
        const back = Buffer.alloc(expected.length);
        const { bytesRead } = await handle.read(back, 0, back.length, 0);
        return back.subarray(0, bytesRead).equals(expected.subarray(0, bytesRead)) && bytesRead >= offset + insert.length
          ? null
          : "The written file does not start as expected.";
      } finally {
        await handle.close();
      }
    };
  }
  await spliceInto(path, offset, insert, check);
}

async function spliceInto(path: string, offset: number, insert: Buffer, check: (temp: string) => Promise<string | null>): Promise<void> {
  const temp = `${path}.thumbnails`;
  const output = await open(temp, "wx");
  try {
    const input = await open(path, "r");
    try {
      const { size } = await input.stat();
      const chunk = Buffer.alloc(1 << 20);
      const copy = async (from: number, to: number) => {
        for (let at = from; at < to; ) {
          const { bytesRead } = await input.read(chunk, 0, Math.min(chunk.length, to - at), at);
          if (bytesRead === 0) throw new Error("The G-code ended while being copied.");
          await output.write(chunk.subarray(0, bytesRead));
          at += bytesRead;
        }
      };
      await copy(0, offset);
      await output.write(insert);
      await copy(offset, size);
    } finally {
      await input.close();
    }
    await output.close();
    const wrong = await check(temp);
    if (wrong) throw new Error(wrong);
    await rename(temp, path);
  } catch (error) {
    await output.close().catch(() => undefined);
    await unlink(temp).catch(() => undefined);
    throw error;
  }
}
